import {interpreter as eager} from './eager/src/interpreter.ts';
import {interpreter as lazy} from './lazy/src/interpreter.ts';
import {standard_operators} from './eager/src/operators.ts';
import {median,sample} from './measure.ts';
const v8:string='node:v8';const {getHeapStatistics}=await import(v8);
const proc:string='node:process';const {cpuUsage}=await import(proc);
const gc=(globalThis as unknown as {gc():void}).gc;
const source='?0 + ?1 * 3';
const languages={eager:eager(standard_operators),lazy:lazy(standard_operators)};
let sink:unknown;
const timing:Record<string,{wall:number;cpu:number}[]>={};
const first:Record<string,{wall:number;cpu:number;calls:number}[]>={};
const memory:Record<string,{allocated_bytes_per_runner:number;retained_bytes_per_runner:number}[]>={};
function checked(run:unknown): (...values:unknown[])=>unknown {if(run instanceof Error)throw run;return run as (...values:unknown[])=>unknown;}
const workloads=Object.entries(languages).flatMap(([name,language])=>{
 const run=checked(language.raw(source));if(run(4,5)!==19)throw new Error('bad workload');
 return [
  {name:name+'/raw-create',run:()=>language.raw(source)},
  {name:name+'/raw-create-execute',run:()=>checked(language.raw(source))(4,5)},
  {name:name+'/hot',run:()=>run(4,5)},
 ];
});
for(const workload of workloads)sample(workload.run,100);
for(let round=0;round<5;round++){
 let order=[...workloads];if(round%2===1)order.reverse();
 for(const {name,run} of order)(timing[name]??=[]).push(sample(run,50));
}
// Preparation stays outside the clock; every runner in each batch executes exactly once.
for(const [name,language] of Object.entries(languages)){
 for(let round=-1;round<5;round++){
  let wall=0,cpu=0,calls=0;const target=50;
  while(wall<target){
   const runners=Array.from({length:2048},()=>checked(language.raw(source)));
   const c=cpuUsage();const start=performance.now();
   for(const run of runners)sink=run(4,5);
   wall+=performance.now()-start;const elapsed=cpuUsage(c);cpu+=elapsed.user+elapsed.system;calls+=runners.length;
  }
  if(round>=0)(first[name]??=[]).push({wall:wall*1e6/calls,cpu:cpu*1000/calls,calls});
 }
}
for(let round=0;round<5;round++)for(const [name,language] of Object.entries(languages))for(const executed of [false,true]){
 let retained:unknown[]=new Array(5000);gc();gc();const before=getHeapStatistics();
 for(let i=0;i<retained.length;i++){const runner=checked(language.raw(source));if(executed)sink=runner(4,5);retained[i]=runner;}
 const allocated=getHeapStatistics().total_allocated_bytes-before.total_allocated_bytes;gc();gc();const after=getHeapStatistics();
 if(retained.length!==5000)throw new Error('bad retention');
 (memory[name+'/'+executed]??=[]).push({allocated_bytes_per_runner:allocated/retained.length,retained_bytes_per_runner:(after.used_heap_size-before.used_heap_size)/retained.length});retained=[];gc();gc();
}
const summary={timing:Object.fromEntries(Object.entries(timing).map(([k,x])=>[k,{wall_ns:median(x.map(s=>s.wall)),cpu_ns:median(x.map(s=>s.cpu))}])),first:Object.fromEntries(Object.entries(first).map(([k,x])=>[k,{wall_ns:median(x.map(s=>s.wall)),cpu_ns:median(x.map(s=>s.cpu))}])),memory:Object.fromEntries(Object.entries(memory).map(([k,x])=>[k,{allocated_bytes_per_runner:median(x.map(s=>s.allocated_bytes_per_runner)),retained_bytes_per_runner:median(x.map(s=>s.retained_bytes_per_runner))}]))};
console.log(JSON.stringify({summary,timing,first,memory,pins:JSON.parse(await Deno.readTextFile(new URL('./pins.json',import.meta.url))),version:Deno.version,method:'timing100mswarmup,5alternating50mswall/CPU samples; firstcall excludes preparation,2048fresh runners/batch,6x50ms(onewarmup); memory5000retainedrunners,fiveforcedGCsamples; no result caching',sink},null,2));

reproduction.measure_source:
interface CpuTime {
  user: number;
  system: number;
}
// The built-in module needs no packages. Dynamic loading avoids pulling the
// unrelated @types/node package into this dependency-free Deno project.
const process_module: string = "node:process";
const { cpuUsage }: { cpuUsage(previous?: CpuTime): CpuTime } = await import(
  process_module
);

let sink: unknown;
/** Time batches with both wall and CPU clocks to expose host contention. */
export function sample(
  run: () => unknown,
  duration: number,
): { wall: number; cpu: number } {
  let count = 0;
  const cpu_start = cpuUsage();
  const start = performance.now();
  let elapsed = 0;
  let batch = 1;
  do {
    for (let index = 0; index < batch; index += 1) sink = run();
    count += batch;
    elapsed = performance.now() - start;
    // Keep slow completion/large-vocabulary cases from overshooting by 100x.
    batch = Math.min(
      100,
      Math.max(1, Math.floor(count / Math.max(elapsed, 0.001))),
    );
  } while (elapsed < duration);
  const cpu = cpuUsage(cpu_start);
  if (sink === Symbol.for("unreachable benchmark sink")) {
    throw new Error("unreachable");
  }
  return {
    wall: elapsed * 1e6 / count,
    cpu: (cpu.user + cpu.system) * 1000 / count,
  };
}

/** Report a middle sample instead of treating scheduler/GC outliers as a trend. */
export function median(values: readonly number[]): number {
  const sorted = values.toSorted((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)];
}

